/** Read-only, deterministic audit. Reads pinned source; emits JSON only to stdout.
 * Usage: node audit-reading-routes.ts <source-root> <all64-records.json>
 * No writes, Git mutations, network requests, generator invocation or deployment.
 */
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {execFileSync, spawnSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {createRequire} from 'node:module';

const sourceCommit = 'ad982a5ff6358155aefc694a9627590722def9f8';
const legacyBaselineCommit = 'd828ab7f73282de64b30a3d85534e1ce401c2bb7';
const sourceRoot = fs.realpathSync(process.argv[2]!);
const recordsPath = fs.realpathSync(process.argv[3]!);
const sha = (value: string | Uint8Array) => 'sha256:' + createHash('sha256').update(value).digest('hex');
const jsonSha = (value: unknown) => sha(JSON.stringify(value));
const git = (...args: string[]) => execFileSync('git', args, {cwd: sourceRoot, maxBuffer: 64 * 1024 * 1024});
assert.equal(git('rev-parse', 'HEAD').toString().trim(), sourceCommit, 'Audit requires the selected source commit');
const initialStatus = git('status', '--porcelain').toString();
assert.equal(initialStatus, '', 'Use the clean pinned source before public-ledger integration');
function pinned(relative: string): Buffer {
  const bytes = fs.readFileSync(path.join(sourceRoot, relative));
  assert.deepEqual(bytes, git('show', sourceCommit + ':' + relative), 'Working source differs from pinned Git source: ' + relative);
  return bytes;
}
function absentAtLegacy(relative: string): boolean {
  const result = spawnSync('git', ['cat-file', '-e', legacyBaselineCommit + ':' + relative], {cwd: sourceRoot, stdio: 'ignore'});
  assert.equal(result.status, 128, 'New source unexpectedly exists at the legacy baseline: ' + relative);
  return true;
}
const runtimeFiles = [
  'packages/pcr-docs/scripts/markdown.ts',
  'packages/pcr-docs/scripts/reading-routes.ts',
  'packages/pcr-docs/scripts/provider-runtime.ts',
  'packages/pcr-docs/scripts/generate.ts',
  'packages/pcr-docs/scripts/summaries.ts',
  'packages/pcr-docs/scripts/language-policy.ts',
  'packages/pcr-core/src/yaml-lite.ts',
  'packages/pcr-core/src/types.ts',
  'package-lock.json',
  'docs/pcr-documentation-site-contract.md',
].map(relative => ({path: relative, sourceCommit, sha256: sha(pinned(relative))}));
const moduleAt = (relative: string) => import(pathToFileURL(path.join(sourceRoot, relative)).href);
const {renderMarkdown, finalizePart, verifyRenderedBlocks} = await moduleAt('packages/pcr-docs/scripts/markdown.ts');
const {canonicalReadingParts} = await moduleAt('packages/pcr-docs/scripts/reading-routes.ts');
const {htmlAnchors, createProviderRuntime} = await moduleAt('packages/pcr-docs/scripts/provider-runtime.ts');
const {documentSummary} = await moduleAt('packages/pcr-docs/scripts/summaries.ts');
const requireFromSource = createRequire(path.join(sourceRoot, 'packages/pcr-docs/package.json'));
const {parseHTML} = requireFromSource('linkedom');
const providerBefore = createProviderRuntime(sourceRoot, sourceCommit);
assert(providerBefore);
type Route = {from: string; to: string; anchor: string};
type AnchorRoute = Route & {anchors: string[]};
type DocumentRow<T> = {sourcePath: string; sourceSha256: string; entries: T[]};
type Ledger<T> = {schemaVersion: number; baselineCommit: string; documents: DocumentRow<T>[]};
const packedPath = 'packages/pcr-docs/compatibility/packed-chapters.json';
const anchorsPath = 'packages/pcr-docs/compatibility/packed-chapter-anchors.json';
const publicPaths = [packedPath, anchorsPath, 'packages/pcr-docs/compatibility/published-chapters.json', 'packages/pcr-docs/compatibility/published-chapter-anchors.json'];
const publicBefore = publicPaths.map(relative => ({path: relative, sourceCommit, bytes: pinned(relative).length, sha256: sha(pinned(relative))}));
const oldPacked = JSON.parse(pinned(packedPath).toString()) as Ledger<Route>;
const oldAnchors = JSON.parse(pinned(anchorsPath).toString()) as Ledger<AnchorRoute>;
assert.equal(oldPacked.baselineCommit, legacyBaselineCommit);
assert.equal(oldAnchors.baselineCommit, legacyBaselineCommit);
assert.equal(oldPacked.documents.length, 105);
assert.equal(oldPacked.documents.reduce((n, d) => n + d.entries.length, 0), 131);
assert.deepEqual(oldAnchors.documents.map(d => ({...d, entries: d.entries.map(({anchors: _anchors, ...route}) => route)})), oldPacked.documents);
const oldDocumentProof = oldPacked.documents.map(document => {
  assert.equal(sha(pinned(document.sourcePath)), document.sourceSha256);
  const baselineBytes = git('show', legacyBaselineCommit + ':' + document.sourcePath);
  return {sourcePath: document.sourcePath, currentSourceSha256: document.sourceSha256, existsAtLegacyBaseline: true, legacySourceSha256: sha(baselineBytes)};
});
const reserved = new Map<string, Route>(providerBefore.routes.map((row: Route) => [row.from, row]));
const oldSources = new Set(oldPacked.documents.map(document => document.sourcePath));
const recordBytes = fs.readFileSync(recordsPath);
const records = JSON.parse(recordBytes.toString()) as {code: string; path: string}[];
assert.equal(records.length, 64);
assert.equal(new Set(records.map(record => record.code)).size, 64);
assert.equal(new Set(records.map(record => record.path)).size, 64);
const additions: DocumentRow<Route>[] = [];
const anchorAdditions: DocumentRow<AnchorRoute>[] = [];
const documents: unknown[] = [];
const ownership: unknown[] = [];
const targetHtmlProofs: unknown[] = [];
let missing = 0, ambiguous = 0, anchorOccurrences = 0;
let sourceNodeChecks = 0, logicalPartsChecked = 0;
const escape = (value: string) => value.replace(/[&<>"']/gu, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]!));

for (const record of records) {
  assert(/^\d{5}$/u.test(record.code));
  assert(/^library\/pcrs\/[a-z0-9-]+\/[a-z0-9-]+\/[a-z0-9-]+$/u.test(record.path));
  for (const [language, locale] of [['en-US', 'en'], ['zh-CN', 'zh']]) {
    const sourcePath = record.path + '/pcr.' + language + '.md';
    assert(!oldSources.has(sourcePath), 'New set overlaps old retained documents');
    const bytes = pinned(sourcePath), sourceSha256 = sha(bytes);
    const absent = absentAtLegacy(sourcePath);
    const unpacked = renderMarkdown(bytes.toString('utf8'), sourcePath, {packAdjacent: false});
    const packed = renderMarkdown(bytes.toString('utf8'), sourcePath, {packAdjacent: true});
    assert.deepEqual(packed.logicalParts, unpacked.logicalParts, 'Logical/search parts changed: ' + sourcePath);
    assert.deepEqual(packed.inventory, unpacked.inventory, 'Source inventory changed: ' + sourcePath);
    const root = '/' + locale + '/docs/pcr/' + record.path.slice('library/pcrs/'.length).split('/').map(encodeURIComponent).join('/') + '/';
    const chapter = (slug: string) => root + 'chapters/' + encodeURIComponent(slug) + '/';
    const url = (part: {slug: string}, index: number) => index ? chapter(part.slug) : root;
    const parts = canonicalReadingParts(packed.parts, chapter, reserved);
    const currentUrls = new Set<string>(parts.map(url));
    assert.deepEqual(parts.map((part: {nodes: unknown}) => part.nodes), packed.parts.map((part: {nodes: unknown}) => part.nodes));
    const anchorOwners = new Map<string, string>();
    parts.forEach((part: {anchors: string[]}, index: number) => part.anchors.forEach(anchor => {
      assert(!anchorOwners.has(anchor), 'Anchor has multiple reading owners');
      anchorOwners.set(anchor, url(parts[index], index));
    }));
    const finalHtml = parts.map((part: {nodes: unknown; sourceHeadingId?: string; sourceNodeIds: string[]}, index: number) => {
      const targetUrl = url(parts[index], index);
      const html = finalizePart(part, {hrefForAnchor: (anchor: string) => {
        const target = anchorOwners.get(anchor);
        assert(target, 'Missing internal anchor target');
        return target + '#' + encodeURIComponent(anchor);
      }});
      // Same ordinary HTML and source-marker wrapper used by renderDocument's verification.
      const title = part.sourceHeadingId ? '<h1 data-source-node="' + part.sourceHeadingId + '">' + escape(packed.title) + '</h1>' : '';
      const verificationHtml = '<html><body>' + title + html + '</body></html>';
      const document = parseHTML(verificationHtml).document;
      verifyRenderedBlocks(document, packed.inventory, part.sourceNodeIds);
      sourceNodeChecks += part.sourceNodeIds.length;
      const anchors = htmlAnchors(html) as Set<string>;
      const counts = new Map<string, number>();
      for (const element of document.querySelectorAll('[id]')) {
        const id = element.getAttribute('id');
        counts.set(id, (counts.get(id) ?? 0) + 1);
      }
      return {targetUrl, htmlSha256: sha(html), bytes: Buffer.byteLength(html), anchors, counts, sourceNodeIdsSha256: jsonSha(part.sourceNodeIds), verifiedSourceNodes: part.sourceNodeIds.length};
    });
    const searchProjection = (rendered: typeof packed) => rendered.logicalParts.map((part: {slug: string; title: string; label: string; sourceNodeIds: string[]; anchors: string[]}, index: number) => {
      const ids = new Set(part.sourceNodeIds);
      const nodes = rendered.inventory.filter((node: {id: string}) => ids.has(node.id));
      const text = nodes.map((node: {text: string}) => node.text).join('\n');
      const description = documentSummary({title: part.title, nodes, fallbackNodes: index === 0 ? rendered.inventory : [], language}).text;
      return {index, url: url(part, index), slug: part.slug, title: part.title, label: part.label, sourceNodeIds: part.sourceNodeIds, anchors: part.anchors, sourceTextSha256: sha(text), sourceTextBytes: Buffer.byteLength(text), description};
    });
    const originalSearch = searchProjection(unpacked), packedSearch = searchProjection(packed);
    assert.deepEqual(packedSearch, originalSearch, 'Search URL/title/summary/text/order changed');
    logicalPartsChecked += originalSearch.length;
    const entries: Route[] = [], anchorEntries: AnchorRoute[] = [];
    const usedTargets = new Set<string>();
    for (const [index, part] of packed.logicalParts.entries()) {
      const from = url(part, index);
      if (currentUrls.has(from)) continue;
      assert(!reserved.has(from), 'New route overlaps an existing reserved source');
      assert(part.anchors.length > 0, 'Removed logical part has no original anchors');
      const candidates = finalHtml.filter(target => part.anchors.every((anchor: string) => target.anchors.has(anchor)));
      if (candidates.length === 0) missing++;
      if (candidates.length > 1) ambiguous++;
      assert.equal(candidates.length, 1, 'Whole logical anchor set lacks one unique ordinary HTML owner');
      const target = candidates[0]!;
      const anchorProof = part.anchors.map((anchor: string) => {
        const owners = finalHtml.filter(page => page.anchors.has(anchor));
        assert.equal(owners.length, 1, 'Anchor lacks unique ordinary HTML owner');
        assert.equal(owners[0]!.targetUrl, target.targetUrl);
        assert.equal(target.counts.get(anchor), 1, 'Anchor is not a unique ordinary HTML id');
        anchorOccurrences++;
        return {anchor, ownerUrl: target.targetUrl, ordinaryHtmlOccurrences: 1, ownerHtmlSha256: target.htmlSha256};
      });
      const entry = {from, to: target.targetUrl, anchor: part.anchors[0]};
      assert(entry.anchor && target.anchors.has(entry.anchor));
      entries.push(entry);
      anchorEntries.push({...entry, anchors: [...part.anchors]});
      usedTargets.add(target.targetUrl);
      ownership.push({code: record.code, language, sourcePath, sourceCommit, sourceSha256, baselineAbsentAt: legacyBaselineCommit, logicalPartIndex: index, from, to: target.targetUrl, defaultAnchor: entry.anchor, originalAnchorArraySha256: jsonSha(part.anchors), anchors: [...part.anchors], targetHtmlSha256: target.htmlSha256, targetHtmlBytes: target.bytes, anchorOwnership: anchorProof, missing: 0, ambiguous: 0});
    }
    if (entries.length) {
      // Runtime ordering is ordinary code-point ordering, independent of locale/ICU.
      entries.sort((a, b) => a.from < b.from ? -1 : a.from > b.from ? 1 : 0);
      anchorEntries.sort((a, b) => a.from < b.from ? -1 : a.from > b.from ? 1 : 0);
      additions.push({sourcePath, sourceSha256, entries});
      anchorAdditions.push({sourcePath, sourceSha256, entries: anchorEntries});
      for (const target of finalHtml.filter(page => usedTargets.has(page.targetUrl))) {
        targetHtmlProofs.push({sourcePath, language, url: target.targetUrl, htmlSha256: target.htmlSha256, bytes: target.bytes, ordinaryHtmlAnchors: [...target.anchors], sourceNodeIdsSha256: target.sourceNodeIdsSha256, verifiedSourceNodes: target.verifiedSourceNodes});
      }
    }
    documents.push({code: record.code, language, sourcePath, sourceCommit, sourceSha256, bytes: bytes.length, absentAtLegacyBaseline: absent, legacyBaselineCommit, logicalParts: unpacked.parts.length, readingParts: parts.length, removedReadingRoutes: entries.length, logicalPartsSha256: jsonSha(unpacked.logicalParts), packedLogicalPartsSha256: jsonSha(packed.logicalParts), logicalPartsDeepEqual: true, sourceInventorySha256: jsonSha(unpacked.inventory), sourceInventoryUnchanged: true, searchProjectionSha256: jsonSha(originalSearch), packedSearchProjectionSha256: jsonSha(packedSearch), searchProjectionDeepEqual: true, searchUnits: originalSearch});
  }
}
assert.equal(documents.length, 128);
assert.equal(additions.length, 28);
assert.equal(ownership.length, 31);
assert.equal(missing, 0);
assert.equal(ambiguous, 0);
assert.deepEqual(anchorAdditions.map(document => ({...document, entries: document.entries.map(({anchors: _anchors, ...route}) => route)})), additions);
const proposedPacked = {...oldPacked, documents: [...oldPacked.documents, ...additions]};
const proposedAnchors = {...oldAnchors, documents: [...oldAnchors.documents, ...anchorAdditions]};
assert.deepEqual(proposedPacked.documents.slice(0, 105), oldPacked.documents);
assert.deepEqual(proposedAnchors.documents.slice(0, 105), oldAnchors.documents);
assert.equal(proposedPacked.baselineCommit, legacyBaselineCommit);
assert.equal(proposedAnchors.baselineCommit, legacyBaselineCommit);
const allRoutes = [...providerBefore.routes, ...additions.flatMap(document => document.entries)] as Route[];
const fromSet = new Set(allRoutes.map(route => route.from));
assert.equal(fromSet.size, allRoutes.length);
assert(allRoutes.every(route => !fromSet.has(route.to)), 'Proposal introduces a route chain or reserved destination');
assert(allRoutes.length < 2000);
assert(Buffer.byteLength(JSON.stringify(proposedPacked, null, 2) + '\n') < 1_000_000, 'Provider packed source exceeds existing budget');
for (const original of publicBefore) assert.equal(sha(pinned(original.path)), original.sha256);
assert.deepEqual(createProviderRuntime(sourceRoot, sourceCommit), providerBefore);
assert.equal(git('status', '--porcelain').toString(), initialStatus);
const report = {
  schemaVersion: 1,
  audit: 'Independent read-only retained-reading-route provenance, losslessness and ordinary-HTML ownership audit',
  reviewer: '/root/pr34_fix_31310',
  sourceRoot, sourceCommit, legacyBaselineCommit,
  evidenceMeaning: {
    legacyScope: 'The root baselineCommit remains the origin baseline of the existing 105-document set; no new source is asserted to exist there.',
    incrementScope: 'The 28 new retained-route documents and all 128 examined new language sources are bound to actual source commit ad982a5ff6358155aefc694a9627590722def9f8 and exact canonical byte hashes.',
    publication: 'No claim of prior route publication, methodology approval, release, deployment, scientific review or study qualification.',
    contractRecommendation: 'Before accepting mixed-baseline append-only data, clarify that the unchanged root baselineCommit describes the legacy set and a reviewed increment receipt supplies the actual source baseline of subsequently added documents.',
    htmlBoundary: 'Ordinary HTML is produced in memory with the pinned exporter finalizePart, parsed and source-block checked like renderDocument, then scanned with its htmlAnchors verifier. This is not a completed Next static export or sealed provider qualification.',
    nextGate: 'Primary controller must review, integrate only the proposed data and minimal contract clarification, then complete fresh generation/search/static-provider/anchor checks and full docs:build under unchanged budgets.',
  },
  execution: {readOnly: true, filesWrittenByScript: [], gitMutations: [], network: false, nodeVersion: process.version, output: 'JSON stdout only; caller may persist it in the authorized private audit directory'},
  input: {recordsPath, recordsSha256: sha(recordBytes), records: records.map(record => ({code: record.code, path: record.path})), runtimeAndContractSources: runtimeFiles},
  summary: {pcrs: 64, languageDocuments: 128, impactedDocuments: additions.length, addedRoutes: ownership.length, checkedOriginalAnchors: anchorOccurrences, missingOwners: missing, ambiguousOwners: ambiguous, oldDocuments: 105, oldPackedRoutes: 131, proposedDocuments: proposedPacked.documents.length, proposedPackedRoutes: proposedPacked.documents.reduce((n, d) => n + d.entries.length, 0), unchangedLogicalSearchUnits: logicalPartsChecked, verifiedSourceNodes: sourceNodeChecks, existingCombinedRoutes: providerBefore.routes.length, proposedCombinedRoutes: allRoutes.length},
  legacyAndPublishedInvariance: {publicFiles: publicBefore.map(row => ({...row, matchesPinnedCommit: true, unchangedAfterAudit: true})), oldPackedDocumentsSha256: jsonSha(oldPacked.documents), proposedOldPrefixSha256: jsonSha(proposedPacked.documents.slice(0, 105)), oldAnchorDocumentsSha256: jsonSha(oldAnchors.documents), proposedOldAnchorPrefixSha256: jsonSha(proposedAnchors.documents.slice(0, 105)), fromDefaultAnchorFullAnchorArraysSourceHashesAndOrderUnchanged: true, legacyBaselineUnchanged: true, publishedLedgersUnchanged: true, providerRuntimeProofUnchangedDuringAudit: true, oldDocumentProof},
  proposedAdditions: {packedDocumentsSha256: jsonSha(additions), anchorDocumentsSha256: jsonSha(anchorAdditions), projectedAnchorLedgerMatchesPackedDocuments: true, existingObjectsPreservedAsExactPrefix: true, perDocumentEntriesSorted: 'code-point order required by routeRows', originalAnchorArrays: 'unchanged source order', sourceCollisions: 0, reservedDestinationsOrChains: 0, existingProviderBudgetSatisfied: true},
  documents, routeOwnership: ownership, ordinaryHtmlTargets: targetHtmlProofs,
};
process.stdout.write(JSON.stringify({report, packedDocuments: additions, anchorDocuments: anchorAdditions}, null, 2) + '\n');
